#!/usr/bin/env node
/**
 * scripts/build-admin-bundle.js
 * 把 pages/admin/*.js 合并到 assets/admin-bundle.js
 * 采用固定模块清单（不依赖 admin.html 现状），可反复运行
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const ADMIN_HTML = path.join(ROOT, 'admin.html');
const OUT_FILE = path.join(ROOT, 'assets/admin-bundle.js');

// 固定模块清单（按加载顺序）
const MODULES = [
    'pages/admin/context.js',
    'pages/admin/settings.js',
    'pages/admin/logs.js',
    'pages/admin/waiter.js',
    'pages/admin/currency.js',
    'pages/admin/store.js',
    'pages/admin/admin-mgr.js',
    'pages/admin/cashier-mgr.js',
    'pages/admin/printer.js',
    'pages/admin/khqr.js',
    'pages/admin/report.js',
    'pages/admin/menu.js',
    'pages/admin/table.js',
    'pages/admin/order.js',
    'pages/admin/shared.js',
    'pages/admin/modals.js',
];

console.log(`📦 固定清单: ${MODULES.length} 个 admin 子模块`);

// 1. 拼接
let bundle = `/* ============================================================
   AUTO-GENERATED by scripts/build-admin-bundle.js — DO NOT EDIT
   源码位置: pages/admin/*.js
   重新生成: npm run build:admin
   生成时间: ${new Date().toISOString()}
   包含 ${MODULES.length} 个模块：
${MODULES.map(f => '     - ' + path.basename(f)).join('\n')}
   ============================================================ */
`;

let totalBytes = 0;
for (const f of MODULES) {
    const fullPath = path.join(ROOT, f);
    if (!fs.existsSync(fullPath)) {
        console.error(`❌ 文件不存在: ${f}`);
        process.exit(1);
    }
    const content = fs.readFileSync(fullPath, 'utf8');
    totalBytes += Buffer.byteLength(content, 'utf8');
    bundle += `\n/* ========== ${f} ========== */\n`;
    bundle += content;
    bundle += '\n';
}

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, bundle, 'utf8');
const outSize = Buffer.byteLength(bundle, 'utf8');
console.log(`✅ assets/admin-bundle.js 生成完成`);
console.log(`   源码合计: ${(totalBytes/1024).toFixed(1)} KB`);
console.log(`   打包产物: ${(outSize/1024).toFixed(1)} KB`);

// 2. 更新 admin.html（幂等）
const ts = Math.floor(Date.now() / 1000);
let html = fs.readFileSync(ADMIN_HTML, 'utf8');

const hasIndividualScripts = /<script\s+src="pages\/admin\/[\w\-]+\.js/.test(html);
const hasBundle = /<script\s+src="assets\/admin-bundle\.js/.test(html);

if (hasIndividualScripts) {
    // 首次或回滚后：删除所有子模块 script，插入 bundle
    const firstMatch = html.match(/([\t ]*)<script\s+src="pages\/admin\/[\w\-]+\.js[^"]*"[^>]*>\s*<\/script>/);
    const indent = firstMatch ? firstMatch[1] : '';

    html = html.replace(
        /[\t ]*<script\s+src="pages\/admin\/[\w\-]+\.js(?:\?[^"]*)?"[^>]*>\s*<\/script>\s*\n?/g,
        ''
    );

    const bundleTag = `${indent}<script src="assets/admin-bundle.js?v=${ts}"></script>\n`;
    const mainJsRe = /([\t ]*)<script\s+src="pages\/admin\.js(?:\?[^"]*)?"[^>]*>\s*<\/script>/;
    const mainMatch = html.match(mainJsRe);
    if (!mainMatch) {
        console.error('❌ 未找到 pages/admin.js 主入口');
        process.exit(1);
    }
    html = html.replace(mainJsRe, `${bundleTag}${mainMatch[0]}`);
    html = html.replace(/(pages\/admin\.js\?v=)\d+/g, `$1${ts}`);
    fs.writeFileSync(ADMIN_HTML, html, 'utf8');
    console.log(`✅ admin.html 已更新（首次替换）`);
    console.log(`   - 删除 ${MODULES.length} 个 script 标签`);
    console.log(`   - 插入 assets/admin-bundle.js?v=${ts}`);

} else if (hasBundle) {
    // 已 bundle 过：只更新版本号
    html = html.replace(/(assets\/admin-bundle\.js\?v=)\d+/g, `$1${ts}`);
    html = html.replace(/(pages\/admin\.js\?v=)\d+/g, `$1${ts}`);
    fs.writeFileSync(ADMIN_HTML, html, 'utf8');
    console.log(`✅ admin.html 版本号已更新（无需替换）`);
    console.log(`   - assets/admin-bundle.js?v=${ts}`);
    console.log(`   - pages/admin.js?v=${ts}`);

} else {
    console.error('❌ admin.html 里既没找到 admin 子模块，也没找到 bundle，请检查');
    process.exit(1);
}
